apiVersion: apps/v1
kind: Deployment
metadata:
  name: {{ include "app.fullname" . }}
  labels:
    {{- include "app.labels" . | nindent 4 }}
spec:
  {{- if not .Values.autoscaling.enabled }}
  replicas: {{ .Values.replicaCount }}
  {{- end }}
  selector:
    matchLabels:
      {{- include "app.selectorLabels" . | nindent 6 }}
  {{- with .Values.deploymentStrategy }}
  strategy:
    {{- toYaml . | trim | nindent 4 }}
  {{- end }}
  template:
    metadata:
      {{- with .Values.podAnnotations }}
      annotations:
        {{- toYaml . | nindent 8 }}
      {{- end }}
      labels:
        {{- include "app.selectorLabels" . | nindent 8 }}
    spec:
      {{- with .Values.imagePullSecrets }}
      imagePullSecrets:
        {{- toYaml . | nindent 8 }}
      {{- end }}
      serviceAccountName: {{ include "app.serviceAccountName" . }}
      securityContext:
        {{- toYaml .Values.podSecurityContext | nindent 8 }}

      volumes:
        - name: data
          {{- if .Values.persistence.enabled }}
          persistentVolumeClaim:
            claimName: {{ .Values.persistence.existingClaim | default (include "app.fullname" .) }}
          {{- else }}
          emptyDir: {}
          {{- end }}

      containers:
        - name: {{ .Chart.Name }}
          securityContext:
            {{- toYaml .Values.securityContext | nindent 12 }}
          image: "{{ .Values.image.repository }}:{{ default .Chart.AppVersion .Values.image.tag }}"
          imagePullPolicy: {{ .Values.image.pullPolicy }}

          ports:
            - name: http
              containerPort: {{ .Values.service.port }}
              protocol: TCP

          livenessProbe:
            initialDelaySeconds: {{ default 60 .Values.probe.liveness.initialDelaySeconds }}
            periodSeconds: {{ default 5 .Values.probe.liveness.periodSeconds }}
            exec:
              command:
              {{- if .Values.probe.liveness.command }}
              {{- toYaml .Values.probe.liveness.command | nindent 14 }}
              {{- else }}
              - pgrep
              - java
              {{- end }}

          readinessProbe:
            initialDelaySeconds: {{ default 60 .Values.probe.readiness.initialDelaySeconds }}
            periodSeconds: {{ default 5 .Values.probe.readiness.periodSeconds }}
            exec:
              command:
              {{- if .Values.probe.readiness.command }}
              {{- toYaml .Values.probe.readiness.command | nindent 14 }}
              {{- else }}
              - pgrep
              - java
              {{- end }}

          env:
            {{- range $key, $value := .Values.app.env_vars }}
            - name: {{ $key }}
              value: {{ $value | quote }}
            {{- end }}
            - name: SPRING_PROFILE
              valueFrom:
                configMapKeyRef:
                  name: {{ include "app.fullname" . }}-config
                  key: SPRING_PROFILE

          args:
            - $(SPRING_PROFILE)

          volumeMounts:
            - name: data
              mountPath: /var/data

          resources:
            {{- toYaml .Values.resources | nindent 12 }}

      {{- with .Values.nodeSelector }}
      nodeSelector:
        {{- toYaml . | nindent 8 }}
      {{- end }}

      {{- with .Values.affinity }}
      affinity:
        {{- toYaml . | nindent 8 }}
      {{- end }}

      {{- with .Values.tolerations }}
      tolerations:
        {{- toYaml . | nindent 8 }}
      {{- end }}

